#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INF 0x3f3f3f3f

static int P[305];
static int G[305];
static int A[305];
static int dp[2][305][2705];

static inline int min_val(int a, int b) {
    return a < b ? a : b;
}

static inline int max_val(int a, int b) {
    return a > b ? a : b;
}

int main(void) {
    int N, K;
    long long T;
    if (scanf("%d %d %lld", &N, &K, &T) != 3) {
        return 0;
    }

    for (int i = 1; i <= N; i++) {
        scanf("%d", &P[i]);
    }

    A[0] = 0;
    for (int i = 1; i <= N; i++) {
        scanf("%d", &G[i]);
        A[i] = A[i - 1] + G[i];
    }

    memset(dp, 0x3f, sizeof(dp));
    dp[0][0][0] = 0;

    for (int i = 1; i <= N; i++) {
        int cur = (i - 1) & 1;
        int nxt = i & 1;

        memset(dp[nxt], 0x3f, sizeof(dp[nxt]));

        int p = P[i];
        int j_min = max_val(0, i - (N - K));
        int j_max = min_val(i, K);

        for (int j = j_min; j <= j_max; j++) {
            int add = abs(A[i] - j);
            int v_max = j * 9;

            for (int v = 0; v <= v_max; v++) {
                int best = dp[cur][j][v];
                if (j > 0 && v >= p) {
                    if (dp[cur][j - 1][v - p] < best) {
                        best = dp[cur][j - 1][v - p];
                    }
                }
                if (best < INF) {
                    dp[nxt][j][v] = best + add;
                }
            }
        }
    }

    int final_step = N & 1;
    int max_brigadeiros = 0;

    for (int v = K * 9; v >= 0; v--) {
        if (dp[final_step][K][v] <= T) {
            max_brigadeiros = v;
            break;
        }
    }

    printf("%d\n", max_brigadeiros);

    return 0;
}
